function seedSnapshot(){const now=new Date().toISOString();return {members:defaultMembers.map((name,i)=>({id:i+1,name,role:'member',active:1,sort_order:i+1,created_at:now,updated_at:now})),departments:defaultDepartments.map((name,i)=>({id:i+1,name,active:1,sort_order:i+1})),ideas:[],cycles:[],projects:[],progress:[]}}
function migrateSnapshot(data){
  const snap=data||seedSnapshot();
  snap.members=Array.isArray(snap.members)?snap.members:[];
  snap.departments=Array.isArray(snap.departments)?snap.departments:[];
  snap.ideas=Array.isArray(snap.ideas)?snap.ideas:[];
  snap.cycles=Array.isArray(snap.cycles)?snap.cycles:[];
  snap.projects=Array.isArray(snap.projects)?snap.projects:[];
  snap.progress=Array.isArray(snap.progress)?snap.progress:[];
  const gowtham=snap.members.find(m=>normalizeName(m.name)==='gowtham');
  if(gowtham)gowtham.name='Gautham';
  const existingNames=new Set(snap.members.map(m=>normalizeName(m.name)));
  defaultMembers.forEach(name=>{if(!existingNames.has(normalizeName(name))){const now=new Date().toISOString();snap.members.push({id:nextId(snap.members),name,role:'member',active:1,sort_order:snap.members.length+1,created_at:now,updated_at:now})}});
  defaultDepartments.forEach((name,i)=>{
    if(snap.departments[i]){snap.departments[i].name=name;snap.departments[i].active=1;snap.departments[i].sort_order=i+1}
    else snap.departments.push({id:i+1,name,active:1,sort_order:i+1});
  });
  snap.departments=snap.departments.slice(0,8);
  snap.schema_version=9;
  snap.updated_at=new Date().toISOString();
  return snap;
}
function rowStamp(row){const v=row?.updated_at||row?.created_at||'';const n=Date.parse(v);return Number.isFinite(n)?n:0}
function mergeById(localRows=[],remoteRows=[]){
  const map=new Map();
  localRows.forEach(row=>map.set(String(row.id),row));
  remoteRows.forEach(row=>{const key=String(row.id),local=map.get(key);if(!local||rowStamp(row)>=rowStamp(local)){const merged={...local,...row};if(local?.attachment?.data&&!row?.attachment?.data)merged.attachment=local.attachment;map.set(key,merged)}});
  return [...map.values()];
}
function mergeSnapshots(local,remote){
  const l=migrateSnapshot(local||seedSnapshot()),r=migrateSnapshot(remote||{});
  return migrateSnapshot({
    members:mergeById(l.members,r.members),
    departments:defaultDepartments.map((name,i)=>({id:i+1,name,active:1,sort_order:i+1})),
    ideas:mergeById(l.ideas,r.ideas),
    cycles:mergeById(l.cycles,r.cycles),
    projects:mergeById(l.projects,r.projects),
    progress:mergeById(l.progress,r.progress)
  });
}
