function storageStatus(){return localStorage.getItem('rnd_storage_persisted')==='1'?'Persistent storage enabled':'Standard browser storage'}
function notificationsEnabled(){return localStorage.getItem('rnd_notifications_enabled')==='1'&&('Notification' in window)&&Notification.permission==='granted'}
async function enableNotifications(){if(!('Notification' in window))throw new Error('Browser notifications are not supported on this browser.');const permission=await Notification.requestPermission();if(permission!=='granted'){localStorage.setItem('rnd_notifications_enabled','0');throw new Error('Notification permission was not granted.')}localStorage.setItem('rnd_notifications_enabled','1');return true}
