function rawSnapshot(){return {schema_version:9,exported_at:new Date().toISOString(),members:state.members.map(({id,name,role='member',active=1,sort_order=0,created_at,updated_at})=>({id,name,role,active,sort_order,created_at,updated_at})),departments:state.departments.map(({id,name,active=1,sort_order=0})=>({id,name,active,sort_order})),ideas:state.ideas.map(({submitted_by_name,department_name,attachment_path,...i})=>i),cycles:state.cycles,projects:state.projects.map(({owner_name,cycle_label,department_name,...p})=>p),progress:state.progress.map(({user_name,attachment_path,...u})=>u)} }
