async function persistState(){const snap=rawSnapshot();await writeSnapshot(snap);return snap}
async function cloudWrite(ops,{silent=false}={}){
  const valid=(ops||[]).filter(x=>x?.collection&&x?.row?.id!==undefined);
  if(!valid.length)return true;
  if(!window.rndCloud?.enabled){queueCloudOps(valid);if(!silent)setCloudRuntimeStatus('offline','Saved locally · waiting for Firebase reconnect');return false}
  try{await window.rndCloud.writeMany(valid);setCloudRuntimeStatus('live');return true}catch(e){queueCloudOps(valid);console.error('Firebase write failed',e);setCloudRuntimeStatus('offline',e?.message||String(e));if(!silent)toast('Saved locally. Firebase will retry when cloud reconnects.',true);return false}
}
