async function assignWeekLocal(cycleId,ideaIds,ownerIds){if(isVisitor())throw new Error('Admin visitors have view-only access.');const cycle=state.cycles.find(c=>c.id===Number(cycleId)),ids=[...new Set((ideaIds||[]).map(Number))];if(!cycle)throw new Error('Weekly cycle not found.');if(ids.length!==2)throw new Error('Exactly 2 ideas must be selected for a weekly assignment.');if(state.projects.some(p=>p.cycle_id===cycle.id))throw new Error('This week already has its two assigned projects.');const ideas=ids.map(id=>state.ideas.find(i=>i.id===id&&i.status==='submitted'));if(ideas.some(x=>!x))throw new Error('Only unassigned submitted ideas can be selected.');const now=new Date().toISOString(),ops=[];ids.forEach((id,idx)=>{const idea=ideas[idx],owner=workingMembers().find(m=>m.id===Number(ownerIds?.[idx]))||workingMembers()[0];if(!owner)throw new Error('Add at least one R&D Member before assigning projects.');const raw={id:nextId(state.projects),cycle_id:cycle.id,idea_id:id,project_number:`RND-${cycle.start_date.slice(0,4)}-W${String(cycle.id).slice(-4)}-${idx+1}`,title:idea.proposed_idea.slice(0,140),owner_id:owner.id,start_date:cycle.start_date,end_date:cycle.end_date,progress:0,status:'assigned',created_at:now,updated_at:now};state.projects.unshift({...raw,owner_name:owner.name,cycle_label:cycle.label,department_name:idea.department_name});idea.status='assigned';idea.updated_at=now;ops.push({collection:'projects',row:raw},{collection:'ideas',row:idea})});cycle.updated_at=now;await persistState();await cloudWrite(ops);notifyUser('Weekly tasks assigned',`${cycle.label}: 2 R&D tasks are now active.`)}
