  const top=$('#liveCloudBadge');
  if(top){top.textContent=status==='live'?'CLOUD LIVE':status==='offline'?'CLOUD OFFLINE':'CLOUD CONNECTING';top.className='cloud-live-badge '+status;top.title=cloudRuntimeMessage||'';}
