function renderWeekly(){const sel=Number($('#weekSelect').value)||state.cycles[0]?.id;if(sel)$('#weekSelect').value=sel;const c=state.cycles.find(x=>x.id===sel);if(!c){$('#weeklySetup').innerHTML='<div class="empty-state">Create a working week to begin shortlisting.</div>';return}const assigned=state.projects.filter(p=>p.cycle_id===c.id);if(assigned.length){$('#weeklySetup').innerHTML=`<div class="panel"><div class="panel-head"><div><span class="kicker">LOCKED WEEKLY ASSIGNMENT</span><h3>${esc(c.label)}</h3></div><span class="tag ${c.status}">${esc(c.status)}</span></div>${assigned.map((p,i)=>`<div class="focus-project"><div class="focus-title"><span>0${i+1} · ${esc(p.title)}</span><span>${p.progress}%</span></div><div class="muted" style="font-size:12px;margin:5px 0">Owner: ${esc(p.owner_name||'—')} · ${fmtDate(p.start_date)} → ${fmtDate(p.end_date)}</div><div class="progress-track"><div class="progress-fill" style="width:${p.progress}%"></div></div></div>`).join('')}</div>`;return}const candidates=state.ideas.filter(i=>i.status==='submitted'&&i.submission_date>=c.start_date&&i.submission_date<=c.end_date);if(isVisitor()){$('#weeklySetup').innerHTML=`<section class="panel"><div class="panel-head"><div><span class="kicker">VIEW ONLY</span><h3>${esc(c.label)} · Available Ideas</h3></div><span class="tag visitor">ADMIN · VISITOR</span></div><div class="visitor-readonly">This account can review weekly ideas and assignments but cannot shortlist or create tasks.</div>${candidates.length?candidates.map(i=>`<div class="idea-choice"><div></div><div><b>${esc(i.proposed_idea)}</b><div class="muted" style="font-size:11px;margin-top:4px">${esc(i.idea_number)} · ${esc(i.submitted_by_name)} · ${esc(i.department_name)}</div><div style="font-size:12px;margin-top:6px">${esc(i.problem)}</div></div></div>`).join(''):'<div class="empty-state">No unassigned ideas available.</div>'}</section>`;return}$('#weeklySetup').innerHTML=`<div class="shortlist-grid"><section class="panel"><div class="panel-head"><div><span class="kicker">UNASSIGNED IDEAS</span><h3>Select 2 Ideas</h3></div></div><div id="candidateIdeas">${candidates.length?candidates.map(i=>`<label class="idea-choice"><input type="checkbox" class="ideaPick" value="${i.id}"><div><b>${esc(i.proposed_idea)}</b><div class="muted" style="font-size:11px;margin-top:4px">${esc(i.idea_number)} · ${esc(i.submitted_by_name)} · ${esc(i.department_name)}</div><div style="font-size:12px;margin-top:6px">${esc(i.problem)}</div></div></label>`).join(''):'<div class="empty-state">No unassigned ideas available. Submit ideas first.</div>'}</div></section><aside class="counter-box"><span class="kicker" style="color:#9eaaa3">WEEKLY RULE</span><div class="counter-num"><span id="pickCount">0</span> / 2</div><p>Exactly two ideas are required. Once assigned, they become this week's execution projects.</p><div id="ownerPickers"></div><button class="secondary-btn" id="assignWeekBtn" style="width:100%;margin-top:14px" disabled>Create Weekly Assignment</button></aside></div>`;bindWeeklyPicks()}
