let currentReport={type:'daily',data:null};async function generateReport(){try{if(state.reportType==='daily'){const date=$('#reportDate')?.value||today(),d=dailyReportLocal(date);currentReport={type:'daily',data:d};const byMember=workingMembers().map(m=>({name:m.name,n:d.ideas.filter(i=>Number(i.submitted_by)===Number(m.id)).length}));$('#reportOutput').innerHTML=`<div class="report-header"><div><span class="kicker">R&D DAILY REPORT</span><h2>${fmtDate(d.date)}</h2></div><b>R&D TRACK</b></div><div class="report-kpis"><div class="report-kpi"><span class="kicker">IDEAS</span><strong>${d.ideas.length}</strong></div><div class="report-kpi"><span class="kicker">UPDATES</span><strong>${d.updates.length}</strong></div><div class="report-kpi"><span class="kicker">PEOPLE SUBMITTED</span><strong>${byMember.filter(x=>x.n).length}/${byMember.length}</strong></div><div class="report-kpi"><span class="kicker">BLOCKERS</span><strong>${d.updates.filter(x=>x.blocker).length}</strong></div></div><div class="analytics-report-grid"><section class="analytics-visual-card"><div class="visual-card-head"><span class="kicker">SUBMISSION DISTRIBUTION</span><b>By member</b></div>${analyticsBars(byMember,Math.max(1,...byMember.map(x=>x.n)),'name','n')}</section><section class="analytics-visual-card"><div class="visual-card-head"><span class="kicker">DAY HEALTH</span><b>${d.updates.filter(x=>x.blocker).length?'Attention needed':'On track'}</b></div><div class="health-ring" style="--score:${Math.round((byMember.filter(x=>x.n).length/Math.max(1,byMember.length))*100)}"><strong>${Math.round((byMember.filter(x=>x.n).length/Math.max(1,byMember.length))*100)}%</strong><span>submission coverage</span></div></section></div><h3>Idea Submission</h3><table class="mini-table"><thead><tr><th>Person</th><th>Ideas</th></tr></thead><tbody>${byMember.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.n}</td></tr>`).join('')}</tbody></table><h3>Project Progress Updates</h3><table class="mini-table"><thead><tr><th>Project</th><th>Person</th><th>Progress</th><th>Work Done</th></tr></thead><tbody>${d.updates.length?d.updates.map(u=>`<tr><td>${esc(u.project_number)}</td><td>${esc(u.user_name)}</td><td>${u.progress_percent}%</td><td>${esc(u.work_done)}</td></tr>`).join(''):'<tr><td colspan="4">No progress updates.</td></tr>'}</tbody></table>`}else{const id=Number($('#reportWeek')?.value||state.cycles[0]?.id);if(!id){$('#reportOutput').innerHTML='<div class="empty-state">Create a week first.</div>';return}const d=weeklyReportLocal(id);currentReport={type:'weekly',data:d};const avg=d.projects.length?Math.round(d.projects.reduce((a,p)=>a+p.progress,0)/d.projects.length):0;$('#reportOutput').innerHTML=`<div class="report-header"><div><span class="kicker">R&D WEEKLY REPORT</span><h2>${esc(d.cycle.label)}</h2><div class="muted">${fmtDate(d.cycle.start_date)} – ${fmtDate(d.cycle.end_date)}</div></div><b>R&D TRACK</b></div><div class="report-kpis"><div class="report-kpi"><span class="kicker">IDEAS SUBMITTED</span><strong>${d.ideas.length}</strong></div><div class="report-kpi"><span class="kicker">SHORTLISTED</span><strong>${d.projects.length}</strong></div><div class="report-kpi"><span class="kicker">COMPLETED</span><strong>${d.projects.filter(p=>p.progress===100).length}</strong></div><div class="report-kpi"><span class="kicker">AVG PROGRESS</span><strong>${avg}%</strong></div></div><div class="analytics-report-grid"><section class="analytics-visual-card"><div class="visual-card-head"><span class="kicker">PROJECT PROGRESS</span><b>${avg}% average</b></div>${analyticsBars(d.projects.map(p=>({label:p.title,value:p.progress})),100,'label','value','%')}</section><section class="analytics-visual-card"><div class="visual-card-head"><span class="kicker">WEEK HEALTH</span><b>${d.projects.filter(p=>p.progress===100).length}/${d.projects.length||0} completed</b></div><div class="health-ring" style="--score:${avg}"><strong>${avg}%</strong><span>overall execution</span></div></section></div><h3>Weekly Projects</h3><table class="mini-table"><thead><tr><th>Project</th><th>Owner</th><th>Progress</th><th>Status</th></tr></thead><tbody>${d.projects.map(p=>`<tr><td>${esc(p.project_number)} · ${esc(p.title)}</td><td>${esc(p.owner_name||'—')}</td><td>${p.progress}%</td><td>${esc(p.status)}</td></tr>`).join('')}</tbody></table><h3>Team Contribution</h3><table class="mini-table"><thead><tr><th>Member</th><th>Ideas</th><th>Progress Updates</th></tr></thead><tbody>${d.contribution.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.idea_count}</td><td>${x.update_count}</td></tr>`).join('')}</tbody></table>`}}catch(e){toast(e.message,true)}}
function downloadExcel(){if(!currentReport.data)return;const table=$('#reportOutput').innerHTML;const html=`<html><head><meta charset="utf-8"></head><body>${table}</body></html>`;const blob=new Blob([html],{type:'application/vnd.ms-excel'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`RND-${currentReport.type}-report.xls`;a.click();URL.revokeObjectURL(a.href)}
function openIdea(){if(isVisitor()){toast('Admin visitors are view-only and do not submit ideas.',true);return}const d=$('#ideaDialog');$('#ideaMember').value=activeUser();$('#ideaDate').value=today();d.showModal()}
function openProgress(p){if(isVisitor()){toast('Admin visitors are view-only.',true);return}$('#progressDialogTitle').textContent=p.project_number+' — Daily Update';$('#progressMember').value=activeUser();$('#progressDate').value=today();$('#progressPercent').value=p.progress;$('#progressForm').dataset.projectId=p.id;$('#progressDialog').showModal()}
function applyRoleAccess(){const visitor=isVisitor();['#quickIdeaBtn','#newIdeaBtn','#newWeekBtn'].forEach(id=>{const el=$(id);if(el)el.classList.toggle('role-hidden',visitor)});const addForm=$('#addMemberForm');if(addForm)addForm.classList.toggle('role-hidden',visitor);const note=$('#visitorNotice');if(note)note.classList.toggle('hidden',!visitor);document.body.classList.toggle('visitor-mode',visitor)}
function showPage(name){state.page=name;$$('.page').forEach(p=>p.classList.remove('active'));$(`#${name}Page`).classList.add('active');$$('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.page===name));const titles={dashboard:'Dashboard',ideas:'Daily Ideas',weekly:'Weekly Tasks',progress:'Progress Tracker',reports:'Analytics',settings:'Settings'};$('#pageTitle').textContent=titles[name];$('#sidebar').classList.remove('open');if(name==='reports')renderReportControls()}
function bind(){
  $('#loginForm').onsubmit=async e=>{e.preventDefault();const name=$('#loginName').value.trim();$('#loginMessage').textContent='';$('#loginSuggestion').innerHTML='';try{const result=findLogin(name);if(result.matched){persistLogin(result.member);$('#loginName').value='';showApp();toast(`Welcome, ${result.member.name}.`);return}$('#loginMessage').textContent=result.error||'Name not found.';if(result.suggestion){$('#loginSuggestion').innerHTML=`<div class="suggestion-box"><span>Did you mean <b>${esc(result.suggestion.name)}</b>?</span><button type="button" class="secondary-btn" id="useSuggestionBtn">Yes, use this name</button></div>`;$('#useSuggestionBtn').onclick=()=>{persistLogin(result.suggestion);$('#loginName').value='';showApp();toast(`Welcome, ${result.suggestion.name}.`)}}}catch(err){$('#loginMessage').textContent=err.message}};
  $('#addMemberForm').onsubmit=async e=>{e.preventDefault();const name=$('#newMemberName').value.trim(),role=$('#newMemberRole').value;try{await addMemberLocal(name,role);e.target.reset();toast('Member added successfully.');await load()}catch(err){toast(err.message,true)}};
  $('#notificationBtn').onclick=async()=>{try{if(notificationsEnabled()){disableNotifications();toast('Notifications disabled.')}else{await enableNotifications();notifyUser('R&D Track notifications','Notifications are now enabled.');toast('Notifications enabled.')}renderSettings()}catch(err){toast(err.message,true)}};
  $('#exportDbBtn').onclick=()=>{exportDatabase();toast('Database backup downloaded.');};
  $('#importDbInput').onchange=async e=>{try{await importDatabaseFile(e.target.files?.[0]);toast('Database restored successfully.');e.target.value='';await load()}catch(err){toast(err.message,true)}};
  $('#requestStorageBtn').onclick=async()=>{const ok=await requestDurableStorage();toast(ok?'Persistent browser storage enabled.':'Browser kept standard storage mode.',!ok);renderSettings()};const ctb=$('#testCloudBtn');if(ctb)ctb.onclick=async()=>{try{ctb.disabled=true;ctb.textContent='Testing…';const r=await window.rndCloud?.test?.();setCloudRuntimeStatus(r?.ok?'live':'offline',r?.ok?'':r?.message||'Firebase test failed');toast(r?.message||'Firebase is not configured.',!r?.ok);renderSettings()}catch(e){setCloudRuntimeStatus('offline',e.message);toast(e.message,true)}finally{ctb.disabled=false;ctb.textContent='Test Firebase connection'}};const crb=$('#retryCloudBtn');if(crb)crb.onclick=async()=>{crb.disabled=true;crb.textContent='RECONNECTING…';setCloudRuntimeStatus('connecting');const r=await window.rndCloud?.reconnect?.(applyRemoteSnapshot,status=>setCloudRuntimeStatus(status?.connected?'live':'offline',status?.message||status?.error?.message||''));if(!r?.ok)setCloudRuntimeStatus('offline',r?.error||'Reconnect failed');else setCloudRuntimeStatus('live');crb.disabled=false;crb.textContent='Reconnect Firebase';renderSettings()};
  $('#logoutBtn').onclick=()=>{clearLogin();$('#loginMessage').textContent='';$('#loginSuggestion').innerHTML='';showLogin()};
  $$('.nav-btn').forEach(b=>b.onclick=()=>showPage(b.dataset.page));$$('[data-go]').forEach(b=>b.onclick=()=>showPage(b.dataset.go));$('#menuBtn').onclick=()=>$('#sidebar').classList.toggle('open');$('#quickIdeaBtn').onclick=openIdea;$('#newIdeaBtn').onclick=openIdea;$('#newWeekBtn').onclick=()=>{if(isVisitor())return toast('Admin visitors are view-only.',true);$('#weekDialog').showModal()};$$('[data-close]').forEach(b=>b.onclick=()=>document.getElementById(b.dataset.close).close());['#ideaSearch','#ideaPersonFilter','#ideaDeptFilter','#ideaDateFilter'].forEach(s=>$(s).addEventListener('input',renderIdeas));$('#clearIdeaFilters').onclick=()=>{$('#ideaSearch').value='';$('#ideaPersonFilter').value='';$('#ideaDeptFilter').value='';$('#ideaDateFilter').value='';renderIdeas()};$('#weekSelect').onchange=renderWeekly;$$('.report-tab').forEach(b=>b.onclick=()=>{$$('.report-tab').forEach(x=>x.classList.remove('active'));b.classList.add('active');state.reportType=b.dataset.report;renderReportControls()});$('#ideaForm').onsubmit=async e=>{e.preventDefault();const submitBtn=e.submitter||e.target.querySelector('button[type="submit"],button:not([type])');if(submitBtn){submitBtn.disabled=true;submitBtn.textContent='SUBMITTING…'}try{const attachment=await fileData($('#ideaAttachment'));const row=await createIdeaLocal({submitted_by:Number($('#ideaMember').value),department_id:Number($('#ideaDepartment').value),problem:$('#ideaProblem').value,proposed_idea:$('#ideaProposal').value,expected_benefit:$('#ideaBenefit').value,priority:$('#ideaPriority').value,submission_date:$('#ideaDate').value,attachment});$('#ideaDialog').close();e.target.reset();disableWritingAssist(e.target);renderAll();toast(row.cloud_saved?`${row.idea_number} saved to Firebase and dashboard updated.`:`${row.idea_number} saved locally · Firebase sync pending.`,!row.cloud_saved)}catch(err){toast(err.message,true)}finally{if(submitBtn){submitBtn.disabled=false;submitBtn.textContent='Submit Idea'}}};$('#weekForm').onsubmit=async e=>{e.preventDefault();try{await createCycleLocal({label:$('#weekLabel').value,start_date:$('#weekStart').value,end_date:$('#weekEnd').value});$('#weekDialog').close();e.target.reset();toast('Working week created.');await load()}catch(err){toast(err.message,true)}};$('#progressForm').onsubmit=async e=>{e.preventDefault();try{const attachment=await fileData($('#progressAttachment'));await addProgressLocal(Number(e.target.dataset.projectId),{user_id:Number($('#progressMember').value),update_date:$('#progressDate').value,progress_percent:Number($('#progressPercent').value),work_done:$('#progressWork').value,remarks:$('#progressRemarks').value,blocker:$('#progressBlocker').value,next_action:$('#progressNext').value,attachment});$('#progressDialog').close();e.target.reset();toast('Progress update saved.');await load()}catch(err){toast(err.message,true)}}}
disableWritingAssist();new MutationObserver(m=>m.forEach(x=>x.addedNodes.forEach(n=>{if(n.nodeType===1)disableWritingAssist(n)}))).observe(document.documentElement,{childList:true,subtree:true});bind();load().catch(e=>{showLogin();$('#loginMessage').textContent=e.message});
